  ["aece2f49d5584b76"] = { "ふむ……そうだな、君に役立ちそうなレシピがある。教えてやろう！", "." },
  ["aed0a54bb5658151"] = { "生前、私は他者を癒やすことに力を注いだ。死してなお、どれほどの苦痛を与えられるか見てみよう！", "." },
  ["aed26b0faff2971e"] = { "ふーむ……", "." },
  ["aed93e2e0d387838"] = { "Scourgeの死体が私の上に積み重なる中、死んだふりをするのが精一杯だった。闇があり、頭上の戦いのくぐもった音だけがあった。鉄のぶつかり合う音、噛み砕き、擦れる音……おぞましく、恐ろしい音だ。そして静寂が訪れた。彼は私を呼んだ！「Fairbanks！Fairbanks、どこにいる？返事をしろ、Fairbanks！」そして信じられぬという響きが返ってきた。裏切りの痛みだ、{race}……", "." },
